operation.add:
$need = (int)$setting['limit'] - count($data['products']);
if ($need > 0) {
	$exclude_ids = array_map(function($p) { return (int)$p['product_id']; }, $data['products']);
	$exclude_sql = $exclude_ids ? "AND p.product_id NOT IN (" . implode(',', $exclude_ids) . ")" : '';
	$fallback = $this->db->query("SELECT p.product_id FROM " . DB_PREFIX . "product p LEFT JOIN " . DB_PREFIX . "product_to_store p2s ON (p.product_id = p2s.product_id) WHERE p.status = '1' AND p.date_available <= NOW() AND p2s.store_id = '" . (int)$this->config->get('config_store_id') . "' AND (p.subtract = '0' OR p.quantity > '0') " . $exclude_sql . " ORDER BY RAND() LIMIT " . (int)$need);
	foreach ($fallback->rows as $row) {
		$fb = $this->model_catalog_product->getProduct($row['product_id']);
		if (!$fb) { continue; }
		$fb_image = $fb['image'] ? $this->model_tool_image->resize($fb['image'], $setting['width'], $setting['height']) : $this->model_tool_image->resize('placeholder.png', $setting['width'], $setting['height']);
		if ($this->customer->isLogged() || !$this->config->get('config_customer_price')) {
			$fb_price = $this->currency->format($this->tax->calculate($fb['price'], $fb['tax_class_id'], $this->config->get('config_tax')), $this->session->data['currency']);
		} else {
			$fb_price = false;
		}
		if (!is_null($fb['special']) && (float)$fb['special'] >= 0) {
			$fb_special = $this->currency->format($this->tax->calculate($fb['special'], $fb['tax_class_id'], $this->config->get('config_tax')), $this->session->data['currency']);
		} else {
			$fb_special = false;
		}
		$data['products'][] = array(
			'product_id'   => $fb['product_id'],
			'thumb'        => $fb_image,
			'name'         => $fb['name'],
			'price'        => $fb_price,
			'special'      => $fb_special,
			'href'         => $this->url->link('product/product', 'product_id=' . $fb['product_id']),
			'model'        => $fb['model'],
			'manufacturer' => $fb['manufacturer'],
			'stock'        => $fb['quantity'] > 0,
		);
	}
}
